To solve this problem, you need to implement a **Global Tooltip Provider**.

Since Next.js components are isolated, you cannot rely on `useState` inside a single component to track the state of *all* tooltips. Instead, you must lift the state up to a Context Provider that wraps your entire application (or the specific section where these tooltips live).

Here is a complete, copy-pasteable solution using **React Context** and **Tailwind CSS** (standard in Next.js).

### 1. Create the Context and Provider

First, create a file to manage the global state of the tooltips.

`context/TooltipContext.tsx`

```tsx
'use client';

import React, { createContext, useContext, useState, ReactNode } from 'react';

// Define the shape of a tooltip
interface TooltipData {
  id: string;
  content: string;
  x: number;
  y: number;
}

interface TooltipContextType {
  activeTooltip: TooltipData | null;
  openTooltip: (id: string, content: string, x: number, y: number) => void;
  closeTooltip: () => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider = ({ children }: { children: ReactNode }) => {
  const [activeTooltip, setActiveTooltip] = useState<TooltipData | null>(null);

  const openTooltip = (id: string, content: string, x: number, y: number) => {
    setActiveTooltip({ id, content, x, y });
  };

  const closeTooltip = () => {
    setActiveTooltip(null);
  };

  return (
    <TooltipContext.Provider value={{ activeTooltip, openTooltip, closeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

### 2. Create the Tooltip Component

This component is isolated. It doesn't know about other tooltips; it just asks the Context for the current state.

`components/Tooltip.tsx`

```tsx
'use client';

import React from 'react';
import { useTooltip } from '@/context/TooltipContext'; // Adjust path as needed

interface TooltipProps {
  id: string;
  content: string;
  x: number;
  y: number;
  trigger: React.ReactNode; // The button or element triggering the tooltip
}

export const Tooltip = ({ id, content, x, y, trigger }: TooltipProps) => {
  const { activeTooltip, openTooltip, closeTooltip } = useTooltip();

  const isActive = activeTooltip?.id === id;

  return (
    <div style={{ position: 'relative', display: 'inline-block' }}>
      {/* The Trigger (e.g., Button) */}
      {trigger}

      {/* The Tooltip Bubble */}
      {isActive && (
        <div
          style={{
            position: 'absolute',
            top: y,
            left: x,
            backgroundColor: 'black',
            color: 'white',
            padding: '8px 12px',
            borderRadius: '4px',
            fontSize: '14px',
            zIndex: 1000,
            pointerEvents: 'none', // Let clicks pass through to the trigger if needed
            whiteSpace: 'nowrap',
            boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
          }}
        >
          {content}
        </div>
      )}
    </div>
  );
};
```

