```java
public class TriangularPattern {
    public static void main(String[] args) {
        int rows = 5; // You can change this number to print more or fewer rows

        for (int i = 1; i <= rows; i++) {
            // Print spaces
            for (int j = 1; j <= rows - i; j++) {
                System.out.print(" ");
            }

            // Print asterisks
            for (int k = 1; k <= i; k++) {
                System.out.print("*");
            }

            // Move to the next line
            System.out.println();
        }
    }
}
```

