Here are the two functions to pack and unpack the data.

### The Logic

1.  **Packing**: We iterate through the entities. For each entity, we take the `id` (4 bits) and `size` (3 bits), concatenate them into a 7-bit integer, and write that integer into the `Uint8Array` at the current offset. We increment the offset by 1 byte (8 bits) for every entity.
2.  **Unpacking**: We iterate through the `Uint8Array`. For each byte, we extract the lower 4 bits for the `id` and the upper 3 bits for the `size`.

### The Code

```javascript
/**
 * Packs an array of entities into a Uint8Array (ArrayBuffer).
 * 
 * @param {Array} entities - Array of objects with { id, size }
 * @returns {Uint8Array} - The packed buffer
 */
function packEntities(entities) {
    if (!Array.isArray(entities)) {
        throw new Error("Input must be an array of entities");
    }

    const buffer = new Uint8Array(entities.length);

    for (let i = 0; i < entities.length; i++) {
        const entity = entities[i];

        // Validate fields
        if (typeof entity.id !== 'number' || typeof entity.size !== 'number') {
            throw new Error(`Entity at index ${i} is missing id or size`);
        }

        // Combine id (4 bits) and size (3 bits) into a single 7-bit integer
        // (id << 3) | size
        const packedValue = (entity.id << 3) | entity.size;

        // Write to buffer
        buffer[i] = packedValue;
    }

    return buffer;
}

/**
 * Unpacks a Uint8Array (ArrayBuffer) into an array of entities.
 * 
 * @param {Uint8Array} buffer - The packed buffer
 * @returns {Array} - Array of objects with { id, size }
 */
function unpackEntities(buffer) {
    if (!(buffer instanceof Uint8Array)) {
        throw new Error("Input must be a Uint8Array");
    }

    const entities = [];

    for (let i = 0; i < buffer.length; i++) {
        const byte = buffer[i];

        // Extract id (lower 4 bits) and size (upper 3 bits)
        const id = byte & 0x0F;       // 0x0F is binary 00001111
        const size = (byte >> 3) & 0x07; // 0x07 is binary 00000111

        entities.push({ id, size });
    }

    return entities;
}

