**The Generator Script (`generator.dart`):**
```dart
import 'dart:convert';
import 'dart:io';

void main() {
  // 1. Read the JSON file
  final jsonFile = File('schema.json');
  final jsonString = jsonFile.readAsStringSync();
  final Map<String, dynamic> schema = json.decode(jsonString);

  // 2. Generate the Dart Class
  final className = schema['name'] ?? 'GeneratedClass';
  final fields = schema['fields'] as List<dynamic>;

  print('// Auto-generated code from $jsonFile\n');
  print('class $className {\n');

  // Generate fields
  for (var field in fields) {
    final fieldName = field['name'];
    final fieldType = field['type'];
    print('  final $fieldName; // $fieldType');
  }

  print('\n  $className.fromJson(Map<String, dynamic> json) {\n');

