// src/test-utils/renderWithResizeObserver.js
import { render, RenderResult } from '@testing-library/react';
import ResizeObserver from 'resize-observer-polyfill'; // Optional: if needed

export function renderWithResizeObserver(ui, options = {}) {
  const { container, ...optionsWithoutContainer } = options;

  // Create a ResizeObserver to simulate window resizing
  const resizeObserver = new ResizeObserver((entries) => {
